def clean(df):
    df = df.copy()
    # exact duplicates
    df = df.drop_duplicates()
    # species typo Adeile -> Adelie
    if 'species' in df.columns:
        df['species'] = df['species'].replace({'Adeile': 'Adelie'})
        # strip whitespace if any
        df['species'] = df['species'].str.strip()
    # island extra spaces " Torgersen", " Biscoe"
    if 'island' in df.columns:
        df['island'] = df['island'].str.strip()
    # sex case variant FEMALE -> female, keep NaN as unknown
    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.strip().str.lower()
    # numbers written as text
    for col in ['flipper_length_mm', 'body_mass_g', 'year', 'bill_length_mm', 'bill_depth_mm']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # out of range body_mass_g 2500-6500, fix factor 1000 error (4850000 -> 4850)
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        if mask.any():
            corrected = df.loc[mask, 'body_mass_g'] / 1000
            valid = corrected.between(2500, 6500)
            df.loc[mask, 'body_mass_g'] = corrected.where(valid, df.loc[mask, 'body_mass_g'])
        df.loc[~df['body_mass_g'].between(2500, 6500), 'body_mass_g'] = pd.NA
    # enforce other ranges (optional, does not affect question)
    if 'bill_length_mm' in df.columns:
        df.loc[~df['bill_length_mm'].between(30, 60), 'bill_length_mm'] = pd.NA
    if 'flipper_length_mm' in df.columns:
        df.loc[~df['flipper_length_mm'].between(170, 235), 'flipper_length_mm'] = pd.NA
    return df

def answer(df):
    # average body mass for each species
    d = df.dropna(subset=['species', 'body_mass_g'])
    # drop missing group keys (groupby excludes NaN)
    g = d.groupby('species', dropna=True)['body_mass_g'].mean()
    return {str(k): float(v) for k, v in g.items()}
